using System;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.UI;
public class CombatUiCompositionTests {
 static Graphic Layer(Graphic owner,string name){var method=owner.GetType().GetMethod("GetLayer");Assert.NotNull(method,"Independent named layer contract required");return (Graphic)method.Invoke(owner,new object[]{name});}
 static GameObject Root()=>new GameObject("composition",typeof(RectTransform),typeof(Canvas));
 static T Add<T>(GameObject root) where T:Graphic {var go=new GameObject(typeof(T).Name,typeof(RectTransform));go.transform.SetParent(root.transform,false);go.GetComponent<RectTransform>().sizeDelta=new Vector2(200,60);return go.AddComponent<T>();}
 static Mesh Mesh(Graphic g){Canvas.ForceUpdateCanvases();return g.canvasRenderer.GetMesh();}
 [TestCase(typeof(CombatTitleBarFrame))][TestCase(typeof(CombatConceptPanel))]
 public void FrameAndPlateHaveIndependentVisibilityAndTransparentFrameCenter(Type type){var root=Root();try{var go=new GameObject("panel",typeof(RectTransform));go.transform.SetParent(root.transform,false);go.GetComponent<RectTransform>().sizeDelta=new Vector2(200,60);var owner=(Graphic)go.AddComponent(type);var frame=Layer(owner,"Frame");var plate=Layer(owner,"Backplate");Assert.AreNotSame(frame,plate);Assert.IsFalse(frame.raycastTarget);Assert.IsFalse(plate.raycastTarget);var fm=Mesh(frame);try{Assert.Greater(fm.vertexCount,0);var v=fm.vertices;var t=fm.triangles;for(int i=0;i<t.Length;i+=3){var center=(v[t[i]]+v[t[i+1]]+v[t[i+2]])/3;Assert.IsFalse(Mathf.Abs(center.x)<70&&Mathf.Abs(center.y)<15,"Frame must not paint central aperture");}}finally{UnityEngine.Object.DestroyImmediate(fm);}plate.enabled=false;Assert.IsTrue(frame.enabled);Assert.IsTrue(owner.gameObject.activeSelf);}finally{UnityEngine.Object.DestroyImmediate(root);}}
 [TestCase(0f)][TestCase(.5f)][TestCase(1f)]
 public void MeterLayersCanHideAndReplaceWithoutChangingValuesOrOtherGeometry(float value){var root=Root();try{var meter=Add<CombatMeter>(root);meter.SetValue(value);var track=Layer(meter,"Track");var fill=Layer(meter,"Fill");var shield=Layer(meter,"Shield");Assert.IsFalse(track.raycastTarget);Assert.IsFalse(fill.raycastTarget);var before=Mesh(track);fill.enabled=false;Canvas.ForceUpdateCanvases();var after=Mesh(track);CollectionAssert.AreEqual(before.vertices,after.vertices);Assert.AreEqual(value,meter.Value);Assert.AreEqual(0,meter.ShieldValue);fill.enabled=true;var replacement=meter.GetType().GetMethod("SetLayerRenderer");Assert.NotNull(replacement);Action<VertexHelper,Rect,Color> draw=(mesh,r,c)=>{mesh.Clear();mesh.AddVert(new Vector3(r.x,r.y),Color.magenta,Vector2.zero);mesh.AddVert(new Vector3(r.xMax,r.y),Color.magenta,Vector2.zero);mesh.AddVert(new Vector3(r.x,r.yMax),Color.magenta,Vector2.zero);mesh.AddTriangle(0,1,2);};replacement.Invoke(meter,new object[]{"Fill",draw});var changed=Mesh(fill);if(value==0)Assert.AreEqual(0,changed.vertexCount);else{Assert.Greater(changed.vertexCount,0);Assert.IsTrue(changed.colors32.All(c=>c.r==255&&c.b==255));foreach(var v in changed.vertices)Assert.LessOrEqual(v.x,-98+196*value+.001f);}Assert.AreEqual(value,meter.Value);Assert.IsTrue(track.enabled);Assert.IsTrue(shield.enabled);UnityEngine.Object.DestroyImmediate(before);UnityEngine.Object.DestroyImmediate(after);UnityEngine.Object.DestroyImmediate(changed);}finally{UnityEngine.Object.DestroyImmediate(root);}}
 [Test] public void ShieldRemainsActualSeparateSegmentWhenFillHidden(){var root=Root();try{var meter=Add<CombatMeter>(root);meter.SetHealth(100,100,50);Layer(meter,"Fill").enabled=false;Assert.AreEqual(100f/150,meter.Value);Assert.AreEqual(50f/150,meter.ShieldValue);var m=Mesh(Layer(meter,"Shield"));Assert.IsTrue(m.colors32.Any(c=>c.r>240&&c.g>240&&c.b>240));UnityEngine.Object.DestroyImmediate(m);}finally{UnityEngine.Object.DestroyImmediate(root);}}
 [Test] public void OwnerLifetimePreservesLayerVisibilityWithoutDuplicateChildren(){var root=Root();try{var panel=Add<CombatTitleBarFrame>(root);var plate=Layer(panel,"Backplate");plate.enabled=false;int count=panel.transform.childCount;panel.enabled=false;Assert.IsFalse(Layer(panel,"Frame").gameObject.activeInHierarchy);panel.enabled=true;Assert.AreEqual(count,panel.transform.childCount);Assert.IsFalse(plate.enabled);Assert.IsTrue(Layer(panel,"Frame").gameObject.activeInHierarchy);int calls=0;panel.SetLayerRenderer("Frame",(m,r,c)=>calls++);Canvas.ForceUpdateCanvases();int before=calls;UnityEngine.Object.DestroyImmediate(panel.gameObject);Canvas.ForceUpdateCanvases();Assert.AreEqual(before,calls);}finally{UnityEngine.Object.DestroyImmediate(root);}}
 [Test] public void HollowMeterFrameDoesNotPaintTheTrackInterior(){var root=Root();try{var meter=Add<CombatMeter>(root);var m=Mesh(Layer(meter,"Frame"));var v=m.vertices;var t=m.triangles;for(int i=0;i<t.Length;i+=3){var c=(v[t[i]]+v[t[i+1]]+v[t[i+2]])/3;Assert.IsFalse(Mathf.Abs(c.x)<70&&Mathf.Abs(c.y)<15);}UnityEngine.Object.DestroyImmediate(m);}finally{UnityEngine.Object.DestroyImmediate(root);}}
 [Test] public void BackplateReplacementCannotPaintTheFrame(){var root=Root();try{var panel=Add<CombatTitleBarFrame>(root);panel.SetLayerRenderer("Backplate",(m,r,c)=>{m.AddVert(new Vector3(r.x,r.y),Color.magenta,Vector2.zero);m.AddVert(new Vector3(r.xMax,r.y),Color.magenta,Vector2.zero);m.AddVert(new Vector3(r.xMax,r.yMax),Color.magenta,Vector2.zero);m.AddVert(new Vector3(r.x,r.yMax),Color.magenta,Vector2.zero);m.AddTriangle(0,1,2);m.AddTriangle(0,2,3);});var mesh=Mesh(Layer(panel,"Backplate"));Assert.Greater(mesh.vertexCount,0);foreach(var v in mesh.vertices){Assert.LessOrEqual(Mathf.Abs(v.x),95.001f);Assert.LessOrEqual(Mathf.Abs(v.y),25.001f);}UnityEngine.Object.DestroyImmediate(mesh);}finally{UnityEngine.Object.DestroyImmediate(root);}}
}

